    if len(panel) < 30:
        return "sideways"
    rets = panel.pct_change().dropna()
    mkt = rets.mean(axis=1)
    r20 = float(mkt.tail(20).mean())
    v20 = float(mkt.tail(20).std())
    trend = r20 / v20 * (20.0 ** 0.5) if v20 and v20 > 1e-12 else 0.0
    if trend > 1.0:
        return "bull"
    if trend < -1.0:
        return "bear"
    return "sideways"


